uniform float speed : 0.5 .. 8.0 = 2.0;
uniform float beam_width : 0.05 .. 0.3 = 0.12;
uniform float beam_softness : 0.0 .. 0.5 = 0.15;
uniform float spin_speed : 0.0 .. 10.0 = 3.0;
uniform float intensity : 0.1 .. 1.0 = 0.8;
uniform bool strobe : false;

state fixed spin_ph;
state fixed beam_ph;
state fixed spin_rate;
state fixed beam_rate;
state fixed half_width;
state fixed softness;
state fixed k_intensity;

void update() {
  spin_rate = fixed(spin_speed);
  beam_rate = fixed(speed);
  half_width = fixed(beam_width * 0.5);
  softness = fixed(beam_softness);
  k_intensity = fixed(intensity);

  spin_ph = fract(spin_ph + fixed(dt) * spin_rate);
  beam_ph = fract(beam_ph + fixed(dt) * beam_rate);
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed y = fixed(led.pos.y);

  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed spin = ang + spin_ph;

  fixed band = fract(s - beam_ph);
  fixed d = abs(band - fixed(0.5));
  fixed edge = half_width + softness;
  fixed beam = clamp((edge - d) / softness, fixed(0.0), fixed(1.0));

  fixed spin_d = abs(fract(spin) - fixed(0.5));
  fixed spin_edge = half_width + softness;
  fixed spin_mask = clamp((spin_edge - spin_d) / softness, fixed(0.0), fixed(1.0));

  fixed combined = beam * spin_mask;

  if (strobe) {
    fixed strobe_ph = fract(beam_ph * fixed(8.0));
    combined = combined * step(fixed(0.5), strobe_ph);
  }

  fixed hue = step(fixed(0.5), band) * fixed(0.6667);
  fixed val = combined * k_intensity;

  return hsv2rgb(hue, fixed(1.0), val);
}

